// GPU 호출이 아닌, 이 단원의 명시적 계약을 검증하는 결정적 CPU 모델이다.
static unsigned checks = 0;
void Check(bool condition, const char* name) {
    ++checks;
    if (!condition) throw std::runtime_error(name); // Release에서도 검사를 유지한다.
}
template < class F > void Reject(F action, const char* name) {
    bool rejected = false;
    try {
        action();
    } catch (const std::exception&) {
        rejected = true;
    }
    Check(rejected, name);
}

// 비용만 검사하는 모델. 실제 register overlap/visibility/SDK 직렬화는 별도 검사다.
unsigned RootCost(unsigned constants, unsigned rootDescriptors, unsigned tables) {
    const std::uint64_t cost = static_cast < std::uint64_t > (constants)+2ull*rootDescriptors+tables;
    if (cost > 64) throw std::invalid_argument("64 DWORD budget exceeded");
    return static_cast < unsigned > (cost);
}
// root 슬롯과 HLSL 레지스터는 다른 번호 체계다. 비용 검사와 실제 SDK 검증은 별개다.
struct Binding { unsigned slot, shaderRegister, space;
};
unsigned FindSlot(const std::vector < Binding > & bindings, unsigned shaderRegister, unsigned space) {
    for (const auto& b:bindings) if (b.shaderRegister == shaderRegister && b.space == space) return b.slot;
    throw std::out_of_range("register not bound");
}
int main() {
    try {
        Check(RootCost(4, 0, 1) == 5, "renderer root size");
        Check(RootCost(1, 1, 0) == 3, "compute root size");
        Check(RootCost(64, 0, 0) == 64, "boundary");
        Reject([] { RootCost(65, 0, 0); }, "over budget");
        Reject([] { RootCost(63, 1, 0); }, "descriptor counts twice");
        Check(RootCost(0, 0, 0) == 0, "empty root");
        Reject([] { RootCost(UINT32_MAX, UINT32_MAX, UINT32_MAX); }, "no arithmetic wrap");
        const std::vector < Binding > b{{0, 3, 0}, {1, 0, 2}};
        Check(FindSlot(b, 3, 0) == 0, "slot differs from register");
        Check(FindSlot(b, 0, 2) == 1, "space distinct");
        Reject([&] { FindSlot(b, 0, 0); }, "wrong register space");
        std::cout << "PASS DX12-06: " << checks << " CPU contract checks\n";
        return 0;
    } catch (const std::exception& e) {
        std::cerr << e.what() << '\n';
        return 1;
    }
}

    void CreateBindingsAndPipeline() {
        // t0 하나를 담는 descriptor table + b0의 float4 root constants.
        D3D12_DESCRIPTOR_RANGE range{};
        range.RangeType = D3D12_DESCRIPTOR_RANGE_TYPE_SRV;
        range.NumDescriptors = 1; range.BaseShaderRegister = 0;
        range.OffsetInDescriptorsFromTableStart = 0;
        D3D12_ROOT_PARAMETER parameters[2]{};
        parameters[0].ParameterType = D3D12_ROOT_PARAMETER_TYPE_DESCRIPTOR_TABLE;
        parameters[0].DescriptorTable = {1, &range};
        parameters[0].ShaderVisibility = D3D12_SHADER_VISIBILITY_PIXEL;
        parameters[1].ParameterType = D3D12_ROOT_PARAMETER_TYPE_32BIT_CONSTANTS;
        parameters[1].Constants = {0, 0, 4};
        parameters[1].ShaderVisibility = D3D12_SHADER_VISIBILITY_PIXEL;
        D3D12_STATIC_SAMPLER_DESC sampler{};
        sampler.Filter = D3D12_FILTER_MIN_MAG_MIP_POINT;
        sampler.AddressU = sampler.AddressV = sampler.AddressW = D3D12_TEXTURE_ADDRESS_MODE_CLAMP;
        sampler.ComparisonFunc = D3D12_COMPARISON_FUNC_ALWAYS;
        sampler.MaxAnisotropy = 1; sampler.MaxLOD = D3D12_FLOAT32_MAX;
        sampler.ShaderRegister = 0; sampler.ShaderVisibility = D3D12_SHADER_VISIBILITY_PIXEL;
        D3D12_ROOT_SIGNATURE_DESC desc{};
        desc.NumParameters = 2; desc.pParameters = parameters;
        desc.NumStaticSamplers = 1; desc.pStaticSamplers = &sampler;
        desc.Flags = D3D12_ROOT_SIGNATURE_FLAG_ALLOW_INPUT_ASSEMBLER_INPUT_LAYOUT;
        ComPtr<ID3DBlob> serialized, errors;
        const auto hr = D3D12SerializeRootSignature(&desc, D3D_ROOT_SIGNATURE_VERSION_1,
            serialized.GetAddressOf(), errors.GetAddressOf());
        if (FAILED(hr) && errors) OutputDebugStringA(static_cast<const char*>(errors->GetBufferPointer()));
        Check(hr, "SerializeRootSignature");
        Check(context.device->CreateRootSignature(0, serialized->GetBufferPointer(),
            serialized->GetBufferSize(), IID_PPV_ARGS(root.GetAddressOf())), "CreateRootSignature");
        // 외부 파일을 읽지 않는 짧은 자체 HLSL. 최신 SM6/DXC 기능의 예제가 아니다.
        const char* shader = R"HLSL(
Texture2D<float4> checker : register(t0);
SamplerState nearestSampler : register(s0);
cbuffer Material : register(b0) { float4 tint; };
struct VertexOut { float4 position : SV_Position; float2 uv : TEXCOORD0; };
VertexOut VSMain(uint vertex : SV_VertexID) {
    const float2 positions[3] = { float2(-0.8,-0.7), float2(0,0.8), float2(0.8,-0.7) };
    const float2 uv[3] = { float2(0,1), float2(0.5,0), float2(1,1) };
    VertexOut result; result.position = float4(positions[vertex],0.5,1);
    result.uv = uv[vertex]; return result;
}
float4 PSMain(VertexOut input) : SV_Target {
    return checker.Sample(nearestSampler, input.uv) * tint;
}
